import { listApiKeys } from "../api/keys";

export function maskApiKey(key) {
  if (!key || key.length <= 4) return "****";
  return "*".repeat(key.length - 4) + key.slice(-4);
}

export function KeyListPage({ keys }) {
  return (
    <table>
      <tbody>
        {keys.map((k) => (
          <tr key={k.id}>
            <td>{k.label}</td>
            <td className="api-key">{maskApiKey(k.value)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

